export interface ProjectLink {
  label: string;
  url: string;
}

/**
 * NOTE: Screenshot generated by `deno task images`. `name` is the source file's
 * basename without extension (`assets/images/projects/ez_1.png` -> `"ez_1"`).
 */
export interface ProjectImage {
  name: string;
  alt: string;
}

/**
 * work: shipped for an employer/client
 * personal: built by me, for real use
 * lab: tinkering and self-hosting, shown for the engineering, not the product
 */
export type ProjectKind = "work" | "personal" | "lab";

export interface Project {
  name: string;
  description: string;
  stack: string[];
  links: ProjectLink[];
  kind: ProjectKind;
  role?: string;
  images?: ProjectImage[];
}
